import { InteractiveGridPattern } from '@exhuma/core';

class ExhumaInteractiveGridPatternElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-interactive-grid');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-interactive-grid')) {
  customElements.define('exhuma-interactive-grid', ExhumaInteractiveGridPatternElement);
}

