import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as InteractiveGridPatternPrimitive from '@exhuma/core';

export interface InteractiveGridPatternProps extends ViewProps {
  children?: React.ReactNode;
}

export function InteractiveGridPattern({ style, children, ...props }: InteractiveGridPatternProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

